function CircularIconButton({ href, onClick, bg, shadow, label, children, imgSrc, imgAlt, ring }) {
  const Tag = href ? "a" : "button";
  const circleSize = 62;
  const circle = (
    <div style={{
      width: circleSize, height: circleSize, borderRadius: "50%", background: bg,
      display: "flex", alignItems: "center", justifyContent: "center",
      boxShadow: shadow, flexShrink: 0, overflow: "hidden",
    }}>
      {imgSrc ? (
        <img src={imgSrc} alt={imgAlt || ""} style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "50%" }} />
      ) : children}
    </div>
  );
  return (
    <Tag
      href={href}
      onClick={onClick}
      target={href ? "_blank" : undefined}
      rel={href ? "noopener noreferrer" : undefined}
      style={{
        display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
        background: "none", border: "none", cursor: "pointer", textDecoration: "none",
        padding: 0, width: 96,
      }}
    >
      {ring ? (
        <div style={{
          width: circleSize + 8, height: circleSize + 8, borderRadius: "50%",
          background: ring, display: "flex", alignItems: "center", justifyContent: "center",
          flexShrink: 0, boxShadow: shadow,
        }}>
          <div style={{
            width: circleSize + 2, height: circleSize + 2, borderRadius: "50%",
            background: C.white, display: "flex", alignItems: "center", justifyContent: "center",
          }}>
            <div style={{
              width: circleSize - 4, height: circleSize - 4, borderRadius: "50%", overflow: "hidden",
              display: "flex", alignItems: "center", justifyContent: "center", background: bg,
            }}>
              {imgSrc ? (
                <img src={imgSrc} alt={imgAlt || ""} style={{ width: "100%", height: "100%", objectFit: "cover", borderRadius: "50%" }} />
              ) : children}
            </div>
          </div>
        </div>
      ) : circle}
      <span style={{ fontFamily: "Poppins", fontWeight: 700, fontSize: 12.5, color: C.navy, textAlign: "center" }}>
        {label}
      </span>
    </Tag>
  );
}

