/* ---------------------------------------------------------------
   MAIN APP
----------------------------------------------------------------*/
const TOTAL_STEPS = 11;

export default function RadiografiaFinanciera() {
  const [screen, setScreen] = useState("intro"); // intro | question | contact | result
  const [step, setStep] = useState(0);
  const [data, setData] = useState({
    name: "",
    age: 27,
    income: 15000,
    savings: 1500,
    dependents: 0,
    employment: null,
    debts: null,
    hasInsurance: null,
    confidence: null,
    priorities: [],
    protectionBudget: 2000,
    goal: 25000,
    phone: "",
    email: "",
    consentPrivacy: false,
    consentMarketing: false,
  });
  const [leadStatus, setLeadStatus] = useState("idle"); // idle | sending | sent | error

  const update = (patch) => setData((d) => ({ ...d, ...patch }));

  const togglePriority = (id) => {
    setData((d) => {
      const has = d.priorities.includes(id);
      if (has) return { ...d, priorities: d.priorities.filter((p) => p !== id) };
      if (d.priorities.length >= 2) {
        return { ...d, priorities: [d.priorities[1], id] };
      }
      return { ...d, priorities: [...d.priorities, id] };
    });
  };

  const isValid = () => {
    switch (step) {
      case 4: return data.employment !== null;
      case 5: return data.debts !== null;
      case 6: return data.hasInsurance !== null;
      case 7: return data.confidence !== null;
      case 8: return data.priorities.length > 0;
      default: return true;
    }
  };

  const goNext = () => {
    if (step === TOTAL_STEPS - 1) {
      setScreen("contact");
    } else {
      setStep((s) => s + 1);
    }
  };
  const goBack = () => {
    if (step === 0) setScreen("intro");
    else setStep((s) => s - 1);
  };

  const restart = () => {
    setData({
      name: "", age: 27, income: 15000, savings: 1500, dependents: 0,
      employment: null, debts: null,
      hasInsurance: null, confidence: null, priorities: [], protectionBudget: 2000, goal: 25000,
      phone: "", email: "", consentPrivacy: false, consentMarketing: false,
    });
    setLeadStatus("idle");
    setStep(0);
    setScreen("intro");
  };

  /* -------------------- RESULT COMPUTATION -------------------- */
  const results = useMemo(() => {
    const savingsRate = data.income > 0 ? (data.savings / data.income) * 100 : 0;
    const recommendedSavings = data.income * 0.15;
    const noBenefits = NO_BENEFITS_EMPLOYMENT.includes(data.employment);

    const savingsScore = clamp((savingsRate / 15) * 100, 0, 100);

    let protectionScore;
    if (data.hasInsurance) {
      protectionScore = 100;
    } else if (data.dependents > 0 && noBenefits) {
      protectionScore = 8;
    } else if (data.dependents > 0) {
      protectionScore = 20;
    } else if (noBenefits) {
      protectionScore = 35;
    } else {
      protectionScore = 55;
    }

    const confidenceScore = data.confidence ? (data.confidence / 5) * 100 : 50;
    const debtOption = DEBT_OPTIONS.find((d) => d.id === data.debts);
    const debtScore = debtOption ? debtOption.score : 60;

    const total = Math.round(
      savingsScore * 0.30 + protectionScore * 0.30 + confidenceScore * 0.15 + debtScore * 0.25
    );

    let band, bandColor, bandBg, badge, message, ctaHeadline;
    if (total < 45) {
      band = "urgente";
      bandColor = C.orange;
      bandBg = C.orangeSoft;
      badge = "🌱 Modo supervivencia";
      message = "Vas al día, y eso está bien para empezar — el siguiente paso es darle estructura a tu dinero antes de que las urgencias decidan por ti.";
      ctaHeadline = "Hablemos hoy: cuanto antes empieces, menos te cuesta.";
    } else if (total < 75) {
      band = "construccion";
      bandColor = C.goldDark;
      bandBg = C.goldSofter;
      badge = "🏗️ Constructor en progreso";
      message = "Ya tienes hábitos de ahorro. Con un plan claro y un poco de protección, puedes acelerar bastante rápido.";
      ctaHeadline = "Vamos afinando el plan para que aceleres más rápido.";
    } else {
      band = "encaminado";
      bandColor = C.navyBrand;
      bandBg = C.navyFaint;
      badge = "🚀 Piloto financiero";
      message = "Vas muy bien encaminado. Ahora se trata de optimizar y proteger lo que ya construiste.";
      ctaHeadline = "Optimicemos y blindemos lo que ya construiste.";
    }

    const coverageMultiplier = data.dependents > 0 ? (noBenefits ? 12 : 10) : (noBenefits ? 7 : 5);
    const suggestedCoverage = Math.round(
      (data.income * 12 * coverageMultiplier) / 10000
    ) * 10000;

    const topPriorities = PRIORITIES.filter((p) => data.priorities.includes(p.id));
    const employmentOption = EMPLOYMENT_OPTIONS.find((e) => e.id === data.employment);

    return {
      savingsRate, recommendedSavings, total, band, bandColor, bandBg,
      badge, message, ctaHeadline, suggestedCoverage, topPriorities,
      noBenefits, employmentOption, debtOption,
    };
  }, [data]);

  /* -------------------- LEAD SUBMISSION (Netlify Forms) -------------------- */
  const submitLead = async (overrides = {}) => {
    setLeadStatus("sending");
    const merged = { ...data, ...overrides };
    const payload = {
      "form-name": "prospectos",
      nombre: merged.name,
      telefono: merged.phone,
      email: merged.email || "(no proporcionado)",
      edad: String(merged.age),
      ingreso_mensual: String(merged.income),
      ahorro_mensual: String(merged.savings),
      dependientes: String(merged.dependents),
      tipo_empleo: results.employmentOption ? results.employmentOption.label : "",
      deudas: results.debtOption ? results.debtOption.label : "",
      tiene_seguro: merged.hasInsurance ? "Sí" : "No",
      nivel_confianza: String(merged.confidence),
      prioridades: results.topPriorities.map((p) => p.label).join(", "),
      presupuesto_proteccion_mensual: String(merged.protectionBudget),
      meta_ahorro_anual: String(merged.goal),
      puntaje: String(results.total),
      banda: results.band,
      insignia: results.badge,
      cobertura_sugerida: String(results.suggestedCoverage),
      acepta_aviso_privacidad: merged.consentPrivacy ? "Sí" : "No",
      acepta_comunicacion_comercial: merged.consentMarketing ? "Sí" : "No",
    };
    try {
      await fetch("/", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams(payload).toString(),
      });
      setLeadStatus("sent");
    } catch (err) {
      // Nunca bloqueamos al usuario si falla el envío — solo lo registramos.
      setLeadStatus("error");
    }
  };

  // Envío LIGERO y separado para cuando alguien acepta comunicación comercial
  // DESPUÉS de ya haber enviado su radiografía completa (ej. al compartir).
  // Va a un formulario distinto ("consentimiento_marketing") para no crear
  // un segundo registro duplicado en "prospectos".
  const submitMarketingConsent = async () => {
    const payload = {
      "form-name": "consentimiento_marketing",
      nombre: data.name,
      telefono: data.phone,
      email: data.email || "(no proporcionado)",
      acepta_comunicacion_comercial: "Sí",
    };
    try {
      await fetch("/", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams(payload).toString(),
      });
    } catch (err) {
      // silencioso: no bloqueamos el flujo de compartir si esto falla
    }
  };

  /* -------------------- STEP CONTENT -------------------- */
  function renderQuestion() {
    switch (step) {
      case 0:
        return (
          <QuestionShell emoji="🎂" title="¿Cuántos años tienes?" subtitle="Nos ayuda a entender en qué momento de tu vida financiera estás.">
            <Slider value={data.age} min={18} max={50} step={1} onChange={(v) => update({ age: v })} formatLabel={(v) => `${v} años`} />
          </QuestionShell>
        );
      case 1:
        return (
          <QuestionShell emoji="💵" title="¿Cuál es tu ingreso mensual aproximado?" subtitle="Puede ser tu sueldo, tus ingresos como freelance, o la suma de ambos.">
            <Slider value={data.income} min={3000} max={100000} step={1000} onChange={(v) => update({ income: v, savings: Math.min(data.savings, v) })} formatLabel={fmtMoney} />
          </QuestionShell>
        );
      case 2: {
        const pct = data.income > 0 ? Math.round((data.savings / data.income) * 100) : 0;
        return (
          <QuestionShell emoji="🐷" title="¿Cuánto de eso logras ahorrar al mes?" subtitle={`Estás ahorrando el ${pct}% de tu ingreso.`}>
            <Slider value={data.savings} min={0} max={data.income} step={500} onChange={(v) => update({ savings: v })} formatLabel={fmtMoney} />
          </QuestionShell>
        );
      }
      case 3:
        return (
          <QuestionShell emoji="👨‍👩‍👧" title="¿Cuántas personas dependen económicamente de ti?" subtitle="Hijos, papás, pareja u otras personas que viven de tu ingreso.">
            <Stepper value={data.dependents} onChange={(v) => update({ dependents: v })} />
          </QuestionShell>
        );
      case 4:
        return (
          <QuestionShell emoji="💼" title="¿Cómo generas tus ingresos?" subtitle="Esto nos ayuda a saber qué tanto respaldo institucional ya tienes.">
            <div style={{ display: "flex", flexDirection: "column", gap: 10, width: "100%" }}>
              {EMPLOYMENT_OPTIONS.map((opt) => (
                <button
                  key={opt.id}
                  onClick={() => update({ employment: opt.id })}
                  style={{
                    display: "flex", alignItems: "center", gap: 14,
                    padding: "13px 18px", borderRadius: 20,
                    border: data.employment === opt.id ? `2px solid ${C.gold}` : `2px solid ${C.navyFaint}`,
                    background: data.employment === opt.id ? C.goldSofter : C.white,
                    cursor: "pointer", textAlign: "left",
                  }}
                >
                  <span style={{ fontSize: 24 }}>{opt.emoji}</span>
                  <span style={{ display: "flex", flexDirection: "column" }}>
                    <span style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 14.5, color: C.navy }}>{opt.label}</span>
                    <span style={{ fontFamily: "Inter", fontSize: 11.5, color: C.navySoft, opacity: 0.65 }}>{opt.sub}</span>
                  </span>
                </button>
              ))}
            </div>
          </QuestionShell>
        );
      case 5:
        return (
          <QuestionShell emoji="💳" title="¿Tienes deudas actualmente?" subtitle="Tarjetas, crédito de auto, préstamos… lo que sea que pese en tu quincena.">
            <div style={{ display: "flex", flexDirection: "column", gap: 10, width: "100%" }}>
              {DEBT_OPTIONS.map((opt) => (
                <button
                  key={opt.id}
                  onClick={() => update({ debts: opt.id })}
                  style={{
                    display: "flex", alignItems: "center", gap: 14,
                    padding: "13px 18px", borderRadius: 20,
                    border: data.debts === opt.id ? `2px solid ${C.gold}` : `2px solid ${C.navyFaint}`,
                    background: data.debts === opt.id ? C.goldSofter : C.white,
                    cursor: "pointer", textAlign: "left",
                  }}
                >
                  <span style={{ fontSize: 24 }}>{opt.emoji}</span>
                  <span style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 15, color: C.navy }}>{opt.label}</span>
                </button>
              ))}
            </div>
          </QuestionShell>
        );
      case 6:
        return (
          <QuestionShell emoji="🛡️" title="¿Ya cuentas con un seguro de vida?" subtitle="No pasa nada si no — para eso estamos aquí.">
            <div style={{ display: "flex", gap: 14, justifyContent: "center", width: "100%" }}>
              <Chip selected={data.hasInsurance === true} onClick={() => update({ hasInsurance: true })}>Sí, tengo</Chip>
              <Chip selected={data.hasInsurance === false} onClick={() => update({ hasInsurance: false })}>Todavía no</Chip>
            </div>
          </QuestionShell>
        );
      case 7:
        return (
          <QuestionShell emoji="🎯" title="¿Qué tan preparado te sientes ante un imprevisto?" subtitle="Un accidente, perder el trabajo, una emergencia médica…">
            <div style={{ display: "flex", flexDirection: "column", gap: 10, width: "100%" }}>
              {CONFIDENCE.map((c) => (
                <button
                  key={c.v}
                  onClick={() => update({ confidence: c.v })}
                  style={{
                    display: "flex", alignItems: "center", gap: 14,
                    padding: "13px 18px", borderRadius: 20,
                    border: data.confidence === c.v ? `2px solid ${C.gold}` : `2px solid ${C.navyFaint}`,
                    background: data.confidence === c.v ? C.goldSofter : C.white,
                    cursor: "pointer", textAlign: "left",
                  }}
                >
                  <span style={{ fontSize: 24 }}>{c.emoji}</span>
                  <span style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 15, color: C.navy }}>{c.label}</span>
                </button>
              ))}
            </div>
          </QuestionShell>
        );
      case 8:
        return (
          <QuestionShell emoji="⭐" title="¿Qué es lo más importante para ti hoy?" subtitle="Elige hasta 2 prioridades.">
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12, width: "100%" }}>
              {PRIORITIES.map((p) => {
                const selected = data.priorities.includes(p.id);
                return (
                  <button
                    key={p.id}
                    onClick={() => togglePriority(p.id)}
                    style={{
                      display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
                      padding: "18px 10px", borderRadius: 22,
                      border: selected ? `2px solid ${C.gold}` : `2px solid ${C.navyFaint}`,
                      background: selected ? C.goldSofter : C.white,
                      cursor: "pointer",
                      position: "relative",
                    }}
                  >
                    {selected && (
                      <div style={{
                        position: "absolute", top: 8, right: 8, width: 20, height: 20, borderRadius: "50%",
                        background: C.gold, display: "flex", alignItems: "center", justifyContent: "center",
                      }}>
                        <Check size={13} color={C.navy} strokeWidth={3} />
                      </div>
                    )}
                    <span style={{ fontSize: 26 }}>{p.emoji}</span>
                    <span style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 12.5, color: C.navy, textAlign: "center", lineHeight: 1.25 }}>
                      {p.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </QuestionShell>
        );
      case 9:
        return (
          <QuestionShell emoji="🪙" title="Si te protegieras con un seguro, ¿cuánto podrías destinar al mes?" subtitle="Solo para tener una idea — nada de esto es un cobro ni un compromiso.">
            <Slider value={data.protectionBudget} min={0} max={3000} step={50} onChange={(v) => update({ protectionBudget: v })} formatLabel={fmtMoney} />
          </QuestionShell>
        );
      case 10:
        return (
          <QuestionShell emoji="🌟" title="¿Cuánto te gustaría ahorrar este año?" subtitle="Una meta anual, aunque sea aproximada.">
            <Slider value={data.goal} min={0} max={300000} step={5000} onChange={(v) => update({ goal: v })} formatLabel={fmtMoney} />
          </QuestionShell>
        );
      default:
        return null;
    }
  }

  /* -------------------- SCREENS -------------------- */
  const FRAME = {
    width: "100%",
    maxWidth: 460,
    minHeight: 680,
    background: C.white,
    borderRadius: 40,
    boxShadow: "0 30px 60px -20px rgba(11,31,61,0.25), 0 0 0 1px rgba(11,31,61,0.04)",
    position: "relative",
    zIndex: 1,
    display: "flex",
    flexDirection: "column",
    overflow: "hidden",
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        width: "100%",
        background: C.cream,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "28px 16px",
        fontFamily: "Inter, sans-serif",
        position: "relative",
      }}
    >
      <style>{`
        ${FONT_IMPORT}
        .luis-slider {
          -webkit-appearance: none;
          appearance: none;
          height: 10px;
          border-radius: 999px;
          outline: none;
        }
        .luis-slider::-webkit-slider-thumb {
          -webkit-appearance: none;
          appearance: none;
          width: 28px;
          height: 28px;
          border-radius: 50%;
          background: ${C.white};
          border: 5px solid ${C.gold};
          box-shadow: 0 4px 10px rgba(253,177,2,0.5);
          cursor: pointer;
        }
        .luis-slider::-moz-range-thumb {
          width: 28px;
          height: 28px;
          border-radius: 50%;
          background: ${C.white};
          border: 5px solid ${C.gold};
          box-shadow: 0 4px 10px rgba(253,177,2,0.5);
          cursor: pointer;
        }
        @keyframes luis-fall {
          to { transform: translateY(560px) rotate(280deg); opacity: 0; }
        }
        @keyframes luis-pop {
          0% { opacity: 0; transform: scale(0.92) translateY(10px); }
          100% { opacity: 1; transform: scale(1) translateY(0); }
        }
        .luis-animate { animation: luis-pop 420ms cubic-bezier(.16,1,.3,1) both; }
      `}</style>

      <BackgroundBlobs />

      <div style={FRAME} className="luis-animate" key={screen + step}>
        {screen === "intro" && <IntroScreen data={data} update={update} onStart={() => setScreen("question")} />}
        {screen === "question" && (
          <div style={{ display: "flex", flexDirection: "column", height: "100%", padding: "26px 26px 22px" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 22 }}>
              <Logo size="sm" />
              <button onClick={restart} style={{ background: "none", border: "none", cursor: "pointer", color: "#B9C1CC" }} title="Reiniciar">
                <RotateCcw size={20} />
              </button>
            </div>
            <ProgressBar step={step} total={TOTAL_STEPS} />
            <div style={{ flex: 1, display: "flex", marginTop: 26 }}>{renderQuestion()}</div>
            <div style={{ display: "flex", gap: 10, marginTop: 22 }}>
              <div style={{ flexShrink: 0 }}>
                <GhostButton onClick={goBack} icon={ArrowLeft} />
              </div>
              <PrimaryButton onClick={goNext} disabled={!isValid()} icon={ArrowRight}>
                {step === TOTAL_STEPS - 1 ? "Ver mi radiografía" : "Siguiente"}
              </PrimaryButton>
            </div>
          </div>
        )}
        {screen === "contact" && (
          <ContactGateScreen
            data={data}
            update={update}
            leadStatus={leadStatus}
            onSubmit={async () => {
              await submitLead();
              setScreen("result");
            }}
          />
        )}
        {screen === "result" && <ResultScreen data={data} results={results} onRestart={restart} onEdit={() => { setScreen("question"); setStep(0); }} update={update} submitMarketingConsent={submitMarketingConsent} />}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   CONTACT GATE SCREEN (captura de lead antes de revelar el resultado)
----------------------------------------------------------------*/
function formatPhoneDisplay(v) {
  const digits = v.replace(/\D/g, "").slice(0, 10);
  const p1 = digits.slice(0, 2), p2 = digits.slice(2, 6), p3 = digits.slice(6, 10);
  return [p1, p2, p3].filter(Boolean).join(" ");
}

function ContactGateScreen({ data, update, leadStatus, onSubmit }) {
  const [touched, setTouched] = useState(false);
  const phoneDigits = data.phone.replace(/\D/g, "");
  const phoneValid = phoneDigits.length === 10;
  const canSubmit = phoneValid && data.consentPrivacy && leadStatus !== "sending";

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", padding: "40px 30px 30px", position: "relative" }}>
      <div style={{
        position: "absolute", top: -60, left: -60, width: 180, height: 180, borderRadius: "50%",
        background: C.goldSoft, opacity: 0.7,
      }} />
      <div style={{
        position: "absolute", bottom: -50, right: -50, width: 150, height: 150, borderRadius: "50%",
        background: C.pinkSoft,
      }} />

      <div style={{ position: "relative", zIndex: 1, flex: 1, display: "flex", flexDirection: "column", justifyContent: "center" }}>
        <div style={{ fontSize: 46, textAlign: "center", marginBottom: 8 }}>🎉</div>
        <h1 style={{
          fontFamily: "Poppins", fontWeight: 800, fontSize: 25, color: C.navy, lineHeight: 1.2,
          margin: 0, textAlign: "center",
        }}>
          ¡Ya está lista tu{" "}
          <span style={{ color: C.gold }}>Radiografía Financiera!</span>
        </h1>
        <p style={{
          fontFamily: "Inter", fontSize: 14.5, color: C.navySoft, opacity: 0.75, marginTop: 12,
          textAlign: "center", lineHeight: 1.5,
        }}>
          Solo dinos a qué WhatsApp te la mandamos, {data.name || "crack"} 👇
        </p>

        <div style={{ marginTop: 26 }}>
          <label style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 13, color: C.navySoft, marginBottom: 8, display: "block" }}>
            Tu WhatsApp
          </label>
          <input
            value={formatPhoneDisplay(data.phone)}
            onChange={(e) => update({ phone: e.target.value.replace(/\D/g, "").slice(0, 10) })}
            onBlur={() => setTouched(true)}
            placeholder="55 1234 5678"
            inputMode="numeric"
            style={{
              width: "100%", fontFamily: "Poppins", fontWeight: 600, fontSize: 17,
              padding: "16px 18px", borderRadius: 18,
              border: `2px solid ${touched && !phoneValid ? C.pink : C.navyFaint}`,
              outline: "none", color: C.navy, boxSizing: "border-box",
            }}
          />
          {touched && !phoneValid && (
            <p style={{ fontFamily: "Inter", fontSize: 11.5, color: C.pink, marginTop: 6, marginBottom: 0 }}>
              Necesitamos un número a 10 dígitos para mandártela.
            </p>
          )}
        </div>

        <div style={{ marginTop: 16 }}>
          <label style={{ fontFamily: "Poppins", fontWeight: 600, fontSize: 13, color: C.navySoft, marginBottom: 8, display: "block" }}>
            Tu correo <span style={{ opacity: 0.55, fontWeight: 500 }}>(opcional)</span>
          </label>
          <input
            value={data.email}
            onChange={(e) => update({ email: e.target.value })}
            placeholder="tu@correo.com"
            type="email"
            style={{
              width: "100%", fontFamily: "Poppins", fontWeight: 600, fontSize: 15,
              padding: "14px 18px", borderRadius: 18, border: `2px solid ${C.navyFaint}`,
              outline: "none", color: C.navy, boxSizing: "border-box",
            }}
          />
        </div>

        <label style={{
          display: "flex", alignItems: "flex-start", gap: 10, marginTop: 18, cursor: "pointer",
        }}>
          <input
            type="checkbox"
            checked={data.consentPrivacy}
            onChange={(e) => update({ consentPrivacy: e.target.checked })}
            style={{ width: 18, height: 18, marginTop: 1, accentColor: C.gold, flexShrink: 0, cursor: "pointer" }}
          />
          <span style={{ fontFamily: "Inter", fontSize: 12, color: C.navySoft, lineHeight: 1.5 }}>
            He leído el{" "}
            <a
              href="https://avisodeprivacidadonline.netlify.app/"
              target="_blank"
              rel="noopener noreferrer"
              onClick={(e) => e.stopPropagation()}
              style={{
                fontFamily: "Inter", fontSize: 12, fontWeight: 700, color: C.goldDark,
                textDecoration: "underline", cursor: "pointer",
              }}
            >
              Aviso de Privacidad
            </a>{" "}
            y conozco que mis datos serán tratados para atender mi solicitud.
          </span>
        </label>
      </div>

      <div style={{ position: "relative", zIndex: 1 }}>
        <PrimaryButton onClick={onSubmit} disabled={!canSubmit} icon={Sparkles}>
          {leadStatus === "sending" ? "Enviando…" : "Ver mi Radiografía"}
        </PrimaryButton>
        <p style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
          fontFamily: "Inter", fontSize: 11, color: "#B9C1CC", marginTop: 12,
        }}>
          🔒 Tu información está segura y nunca la compartimos.
        </p>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   INTRO SCREEN
----------------------------------------------------------------*/
